// ============================================
// NOTIFICATION - уведомления
// ============================================

const data = $input.first().json;

console.log(`📧 ОТПРАВКА УВЕДОМЛЕНИЯ`);
console.log(`📦 Заказ: ${data.orderId}`);
console.log(`💰 Сумма: ${data.total} руб.`);
console.log(`💳 Счет: ${data.invoiceId}`);

// Формируем сообщение
const message = `
🎉 ЗАКАЗ ВЫПОЛНЕН!

━━━━━━━━━━━━━━━━━━━━━
📋 Номер заказа: ${data.orderId}
💰 Сумма: ${data.total} руб.
💳 Номер счета: ${data.invoiceId}
📦 Товаров: ${data.items} шт.
⏰ Время: ${new Date().toLocaleString()}
━━━━━━━━━━━━━━━━━━━━━

Спасибо за покупку!
`;

console.log('📝 Сообщение отправлено клиенту');

return [{
  json: {
    sent: true,
    orderId: data.orderId,
    customerId: data.customerId,
    message: message.substring(0, 100) + '...'
  }
}];

// ============================================
// ОТПРАВКА УВЕДОМЛЕНИЯ В EVENT STORE
// ============================================

const data = $input.first().json;

// Формируем событие
const eventData = {
  eventId: 'notif_' + Date.now(),
  eventType: 'notification.sent',
  timestamp: new Date().toISOString(),
  data: {
    orderId: data.orderId,
    customerId: data.customerId
  },
  source: 'notification'
};

console.log('📧 Отправляем в Event Store:', eventData);
console.log('📦 Заказ:', data.orderId);
console.log('👤 Клиент:', data.customerId);

// Отправляем HTTP запрос
await $http.post('/webhook/event-store', {
  headers: {
    'Content-Type': 'application/json'
  },
  body: eventData
});

console.log('✅ Событие уведомления сохранено');

return [data];
